// Workspace size constants
constexpr uint32_t ASCEND910B_S1_BASE_SIZE = 1024 * 128;
constexpr uint32_t ASCEND910B_S2_BASE_SIZE = 1024 * 64;
// ... 其他平台的常量定义 ...

// gemini-code-assist[bot] 指出：uint32_t 在序列长度超过 300K 时可能溢出
// 例如 seq_len=12M, 24 AIC cores 时 workspace 需要 ~4.6 GB，超过 uint32_t 上限 4 GB
uint32_t workspaceSize = ascendcPlatform.GetLibApiWorkSpaceSize();

// ASCEND950 特定的常量直接嵌入在分支逻辑中（maoxx241 评审：常量与分支逻辑混杂）
if (soc_version == "ASCEND950") {
    // 魔法数字 1024*256 和 1024*128 散落在分支中，未使用命名常量
    workspaceSize = 1024 * 256 + 1024 * 128;
} else if (soc_version == "ASCEND910B") {
    workspaceSize = ASCEND910B_S1_BASE_SIZE + ASCEND910B_S2_BASE_SIZE;
}

