// 分支逻辑中使用命名常量，不再散落魔法数字（+4/-2 行）
if (soc_version == "ASCEND950") {
    workspaceSize = ASCEND950_S1_BASE_SIZE + ASCEND950_S2_BASE_SIZE;
} else if (soc_version == "ASCEND910B") {
    workspaceSize = ASCEND910B_S1_BASE_SIZE + ASCEND910B_S2_BASE_SIZE;
}

